  Intent back=getPackageManager().getLaunchIntentForPackage(getPackageName());if(back==null)back=new Intent(this,MainActivity.class);back.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent action=PendingIntent.getActivity(this,0,back,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return builder.setSmallIcon(android.R.drawable.ic_menu_edit).setContentTitle("Kopy Notes display annotation").setContentText("Tap to return to your lesson").setContentIntent(action).setOngoing(true).setCategory(Notification.CATEGORY_SERVICE).setOnlyAlertOnce(true).addAction(new Notification.Action.Builder(null,"Return to notes",action).build()).build();
