 private float passThroughAlpha(){if(Build.VERSION.SDK_INT>=31){InputManager input=getSystemService(InputManager.class);return Math.min(.70f,input.getMaximumObscuringOpacityForTouch()*.95f);}return .70f;}
 private int screenWidth(){DisplayMetrics size=new DisplayMetrics();manager.getDefaultDisplay().getRealMetrics(size);return size.widthPixels;}
