 private void createToolbar(){toolbar=new LinearLayout(this);toolbar.setOrientation(LinearLayout.VERTICAL);toolbar.setPadding(dp(4),dp(4),dp(4),dp(4));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(Color.rgb(31,40,50));bg.setCornerRadius(dp(14));bg.setStroke(dp(1),Color.rgb(89,103,118));toolbar.setBackground(bg);toolbar.setElevation(dp(8));
  LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);toolbar.addView(row);
  IconButton grip=new IconButton("grip");grip.setContentDescription("Move annotation toolbar");row.addView(grip,new LinearLayout.LayoutParams(dp(32),dp(52)));grip.setOnTouchListener((view,event)->{wake();if(event.getAction()==MotionEvent.ACTION_DOWN){dragX=event.getRawX();dragY=event.getRawY();startX=toolParams.x;startY=toolParams.y;return true;}if(event.getAction()==MotionEvent.ACTION_MOVE){toolParams.x=startX+Math.round(event.getRawX()-dragX);toolParams.y=startY+Math.round(event.getRawY()-dragY);clampToolbar();return true;}if(event.getAction()==MotionEvent.ACTION_UP){getSharedPreferences("kopy-display",0).edit().putInt("toolbarX",toolParams.x).putInt("toolbarY",toolParams.y).apply();view.performClick();return true;}return false;});
  HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);row.addView(scroll,new LinearLayout.LayoutParams(0,dp(52),1));LinearLayout tools=new LinearLayout(this);scroll.addView(tools);
  for(String name:new String[]{"mouse","pen","marker","eraser","line","rect","circle","laser","undo","redo","capture","clear","settings"}){IconButton button=new IconButton(name);buttons.put(name,button);button.setContentDescription(label(name));tools.addView(button,new LinearLayout.LayoutParams(dp(52),dp(52)));button.setOnClickListener(view->select(name));}
  IconButton back=new IconButton("return");back.setContentDescription("Return to notes");row.addView(back,new LinearLayout.LayoutParams(dp(52),dp(52)));back.setOnClickListener(view->returnToNotes());
  options=new LinearLayout(this);options.setGravity(Gravity.CENTER_VERTICAL);options.setVisibility(View.GONE);toolbar.addView(options);HorizontalScrollView swatches=new HorizontalScrollView(this);swatches.setHorizontalScrollBarEnabled(false);LinearLayout colors=new LinearLayout(this);swatches.addView(colors);options.addView(swatches,new LinearLayout.LayoutParams(0,dp(48),1));for(int shade:new int[]{0xffff4b57,0xffffd653,0xff73dc98,0xff75bfff,0xffcfa6ff,Color.WHITE,Color.BLACK}){View chip=new View(this);android.graphics.drawable.GradientDrawable circle=new android.graphics.drawable.GradientDrawable();circle.setColor(shade);circle.setShape(android.graphics.drawable.GradientDrawable.OVAL);circle.setStroke(dp(1),0xffa8b2c1);chip.setBackground(circle);chip.setContentDescription("Ink color "+String.format("#%06X",shade&0xffffff));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(dp(30),dp(30));params.setMargins(dp(7),dp(6),dp(7),dp(6));colors.addView(chip,params);chip.setOnClickListener(view->{color=shade;message("Ink color changed");wake();});}
  SeekBar size=new SeekBar(this);size.setMax(39);size.setProgress(4);size.setContentDescription("Annotation size");options.addView(size,new LinearLayout.LayoutParams(dp(150),dp(48)));size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){width=value+1;if(user){message("Size "+(value+1));wake();}}public void onStartTrackingTouch(SeekBar bar){wake();}public void onStopTrackingTouch(SeekBar bar){}});
  status=new TextView(this);status.setTextColor(0xffcbd5e1);status.setTextSize(11);status.setPadding(dp(10),0,dp(10),dp(3));status.setMaxLines(2);toolbar.addView(status);message("Mouse mode");
 }
 private String label(String name){switch(name){case "mouse":return "Touch through to other apps";case "marker":return "Highlighter";case "capture":return "Save screenshot";case "settings":return "Ink color and size";default:return Character.toUpperCase(name.charAt(0))+name.substring(1);}}
 private void clampToolbar(){if(toolParams==null||toolbar==null)return;toolParams.width=Math.min(dp(800),Math.max(dp(200),screenWidth()-dp(16)));toolParams.x=Math.max(dp(4),Math.min(toolParams.x,screenWidth()-toolParams.width-dp(4)));int height=toolbar.getHeight()>0?toolbar.getHeight():dp(110);toolParams.y=Math.max(dp(4),Math.min(toolParams.y,screenHeight()-height-dp(4)));if(attached||toolbar.isAttachedToWindow())manager.updateViewLayout(toolbar,toolParams);}
 private void wake(){if(toolbar==null)return;toolbar.animate().cancel();toolbar.setAlpha(1);if(fade!=null)main.removeCallbacks(fade);fade=()->{if(attached&&!capturing)toolbar.animate().alpha(.42f).setDuration(220).start();};main.postDelayed(fade,5000);}
 private void select(String selected){wake();if(restoring&&!Arrays.asList("mouse","settings","capture").contains(selected)){message("Please wait, loading annotations...");return;}switch(selected){case "mouse":setDrawing(false);message("Mouse mode");break;case "undo":if(!undo.isEmpty()){redo.addLast(new ArrayList<>(marks));replace(undo.removeLast());save();}break;case "redo":if(!redo.isEmpty()){undo.addLast(new ArrayList<>(marks));replace(redo.removeLast());save();}break;case "clear":if(!marks.isEmpty()){remember();marks.clear();ink.invalidate();save();}break;case "capture":if(!capturing){capturing=true;toolbar.setVisibility(View.GONE);try{startActivity(new Intent(this,AnnotationCaptureActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception error){captureCancelled("Could not request screen capture.");}}break;case "settings":options.setVisibility(options.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);toolbar.post(this::clampToolbar);break;default:tool=selected;setDrawing(true);message(label(selected));}updateButtons();}
 private void setDrawing(boolean enabled){finishStroke();drawing=enabled;inkParams.flags=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|(enabled?0:WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE);inkParams.alpha=enabled?1:passThroughAlpha();manager.updateViewLayout(ink,inkParams);updateButtons();}
 private void updateButtons(){for(Map.Entry<String,IconButton> entry:buttons.entrySet()){entry.getValue().selected=entry.getKey().equals("mouse")?!drawing:drawing&&entry.getKey().equals(tool);entry.getValue().invalidate();}}
 private void remember(){undo.addLast(new ArrayList<>(marks));while(undo.size()>40)undo.removeFirst();redo.clear();}
 private void replace(ArrayList<Mark> next){marks.clear();marks.addAll(next);ink.invalidate();}
 private int pointCount(){int count=0;for(Mark mark:marks)count+=mark.points.size();return count;}
 private void finishStroke(){if(draft!=null&&!draft.points.isEmpty()){remember();marks.add(draft);draft=null;ink.invalidate();save();}activePointer=-1;}
 private void save(){if(pendingSave!=null)main.removeCallbacks(pendingSave);pendingSave=()->{String data=encode();files.execute(()->{try{annotationFiles.save(data);persistedToFolder=true;main.post(()->message(drawing?label(tool):"Mouse mode"));}catch(Exception error){main.post(()->message("Saved in app; choose/re-enable your device folder to keep annotations after uninstall."));}try{android.util.AtomicFile file=new android.util.AtomicFile(new File(getFilesDir(),"display-annotation.json"));FileOutputStream output=file.startWrite();try{output.write(data.getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(output);}catch(Exception error){file.failWrite(output);}}catch(Exception ignored){}});};main.postDelayed(pendingSave,600);}
 private String encode(){JSONObject root=new JSONObject();JSONArray entries=new JSONArray();try{root.put("format","kopy-android-display");root.put("version",1);for(Mark mark:marks)if(!mark.tool.equals("laser")){JSONObject entry=new JSONObject();entry.put("tool",mark.tool);entry.put("color",mark.color);entry.put("width",mark.width);JSONArray points=new JSONArray();for(Sample sample:mark.points){JSONArray point=new JSONArray();point.put(sample.x);point.put(sample.y);point.put(sample.pressure);points.put(point);}entry.put("points",points);entries.put(entry);}root.put("marks",entries);}catch(JSONException ignored){}return root.toString();}
 private void restore(){files.execute(()->{String data=null;try{data=annotationFiles.restore();persistedToFolder=data!=null;}catch(Exception ignored){}if(data==null)try{File source=new File(getFilesDir(),"display-annotation.json");if(source.length()<8*1024*1024)try(InputStream input=new FileInputStream(source);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)out.write(buffer,0,n);data=out.toString("UTF-8");}}catch(Exception ignored){}
  ArrayList<Mark> restored=new ArrayList<>();try{if(data!=null){JSONObject root=new JSONObject(data);if(!"kopy-android-display".equals(root.getString("format"))||root.getInt("version")!=1)throw new IOException("Invalid annotations");JSONArray entries=root.getJSONArray("marks");int count=0;if(entries.length()>2000)throw new IOException("Too many annotations");for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i);String kind=entry.getString("tool");if(!Arrays.asList("pen","marker","line","rect","circle").contains(kind))throw new IOException("Invalid annotation tool");float w=(float)entry.getDouble("width");if(!Float.isFinite(w)||w<1||w>40)throw new IOException("Invalid ink width");Mark mark=new Mark(kind,entry.getInt("color"),w);JSONArray points=entry.getJSONArray("points");count+=points.length();if(count>150000)throw new IOException("Too many points");for(int j=0;j<points.length();j++){JSONArray point=points.getJSONArray(j);float x=(float)point.getDouble(0),y=(float)point.getDouble(1),p=(float)point.optDouble(2,1);if(!Float.isFinite(x)||!Float.isFinite(y)||!Float.isFinite(p)||Math.abs(x)>2||Math.abs(y)>2)throw new IOException("Invalid annotation position");mark.points.add(new Sample(x,y,Math.max(.1f,Math.min(1,p))));}if(!mark.points.isEmpty())restored.add(mark);}}}catch(Exception invalid){restored.clear();}
  main.post(()->{restoring=false;if(attached&&marks.isEmpty()&&draft==null){marks.addAll(restored);ink.invalidate();if(!persistedToFolder)message("Choose a device folder in Kopy settings for uninstall-safe annotation copies.");}});
 });}
 private void returnToNotes(){finishStroke();if(pendingSave!=null){main.removeCallbacks(pendingSave);pendingSave.run();pendingSave=null;}getSharedPreferences("kopy-display",0).edit().putBoolean("returnPending",true).apply();Intent launch=getPackageManager().getLaunchIntentForPackage(getPackageName());if(launch!=null){launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(launch);}stopSelf();}
 private void capture(int result,Intent consent){if(consent==null){captureCancelled("Screenshot permission was not granted.");return;}capturing=true;toolbar.setVisibility(View.GONE);try{
  DisplayMetrics display=new DisplayMetrics();manager.getDefaultDisplay().getRealMetrics(display);float scale=Math.min(1,1920f/Math.max(display.widthPixels,display.heightPixels));int w=Math.max(1,Math.round(display.widthPixels*scale)),h=Math.max(1,Math.round(display.heightPixels*scale));
  MediaProjectionManager projectionManager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=projectionManager.getMediaProjection(result,consent);if(projection==null)throw new IOException("Screenshot consent expired.");MediaProjection owner=projection;projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){main.post(()->{if(projection==owner)endCapture("Screen capture ended.");});}},main);
  reader=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(source->{Image image=null;Bitmap padded=null,cropped=null;try{image=source.acquireLatestImage();if(image==null)return;Image.Plane plane=image.getPlanes()[0];ByteBuffer pixels=plane.getBuffer();int stride=plane.getPixelStride(),padding=plane.getRowStride()-stride*w;padded=Bitmap.createBitmap(w+padding/stride,h,Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(pixels);cropped=Bitmap.createBitmap(padded,0,0,w,h);ByteArrayOutputStream output=new ByteArrayOutputStream();cropped.compress(Bitmap.CompressFormat.PNG,100,output);byte[] png=output.toByteArray();files.execute(()->{try{annotationFiles.screenshot(png);main.post(()->message("Screenshot saved in device folder / Annotations"));}catch(Exception error){main.post(()->message("Screenshot not saved: "+error.getMessage()));}});endCapture(null);}catch(Exception error){endCapture("Could not capture this screen.");}finally{if(image!=null)image.close();if(cropped!=null&&cropped!=padded)cropped.recycle();if(padded!=null)padded.recycle();}},main);
  virtualDisplay=projection.createVirtualDisplay("Kopy Notes screenshot",w,h,display.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,main);captureTimeout=()->endCapture("Screenshot timed out. Try again.");main.postDelayed(captureTimeout,8000);
 }catch(Exception error){endCapture("Could not capture this screen: "+error.getMessage());}}
 private void endCapture(String text){if(captureTimeout!=null){main.removeCallbacks(captureTimeout);captureTimeout=null;}if(virtualDisplay!=null){virtualDisplay.release();virtualDisplay=null;}if(reader!=null){reader.close();reader=null;}if(projection!=null){MediaProjection old=projection;projection=null;old.stop();}capturing=false;if(toolbar!=null)toolbar.setVisibility(View.VISIBLE);if(attached){foreground(false);if(text!=null)message(text);wake();}}
 @Override public void onConfigurationChanged(Configuration next){super.onConfigurationChanged(next);main.postDelayed(()->{if(resize!=null)resize.run();},100);}
 @Override public void onDestroy(){finishStroke();if(pendingSave!=null){main.removeCallbacks(pendingSave);pendingSave.run();pendingSave=null;}attached=false;main.removeCallbacksAndMessages(null);endCapture(null);if(ink!=null)try{manager.removeViewImmediate(ink);}catch(Exception ignored){}if(toolbar!=null)try{manager.removeViewImmediate(toolbar);}catch(Exception ignored){}files.shutdown();current=null;stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
 private static final class Sample {final float x,y,pressure;Sample(float x,float y,float pressure){this.x=x;this.y=y;this.pressure=pressure;}}
 private static final class Mark {final String tool;final int color;final float width;final long created=SystemClock.uptimeMillis();final ArrayList<Sample> points=new ArrayList<>();Mark(String tool,int color,float width){this.tool=tool;this.color=color;this.width=width;}}
 private class InkView extends View {
  private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);InkView(){super(DisplayAnnotationService.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);setContentDescription("Display annotation canvas");}
  private float x(Sample point){return point.x*getWidth();}private float y(Sample point){return point.y*getHeight();}
  @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);long now=SystemClock.uptimeMillis();boolean laser=false;for(Mark mark:marks){draw(canvas,mark,now);if(mark.tool.equals("laser")&&now-mark.created<3500)laser=true;}if(draft!=null)draw(canvas,draft,now);if(laser)postInvalidateOnAnimation();}
  private void draw(Canvas canvas,Mark mark,long now){if(mark.points.isEmpty())return;paint.reset();paint.setAntiAlias(true);paint.setStyle(Paint.Style.STROKE);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);paint.setColor(mark.color);paint.setStrokeWidth(dp(mark.width));if(mark.tool.equals("marker"))paint.setAlpha(90);if(mark.tool.equals("laser")){if(now-mark.created>=3500)return;paint.setAlpha(Math.round(255*Math.max(0,1-(now-mark.created)/3500f)));paint.setShadowLayer(dp(8),0,0,mark.color);}Sample a=mark.points.get(0),b=mark.points.get(mark.points.size()-1);float ax=x(a),ay=y(a),bx=x(b),by=y(b);
   switch(mark.tool){case "rect":canvas.drawRect(Math.min(ax,bx),Math.min(ay,by),Math.max(ax,bx),Math.max(ay,by),paint);break;case "circle":canvas.drawCircle((ax+bx)/2,(ay+by)/2,Math.max(1,Math.min(Math.abs(bx-ax),Math.abs(by-ay))/2),paint);break;case "line":canvas.drawLine(ax,ay,bx,by,paint);break;default:if(mark.points.size()==1){paint.setStyle(Paint.Style.FILL);canvas.drawCircle(ax,ay,dp(mark.width)/2f,paint);}else for(int i=1;i<mark.points.size();i++){Sample p=mark.points.get(i-1),q=mark.points.get(i);paint.setStrokeWidth(dp(mark.width)*(mark.tool.equals("pen")?.25f+.75f*(p.pressure+q.pressure)/2:1));canvas.drawLine(x(p),y(p),x(q),y(q),paint);}break;}
  }
  @Override public boolean onTouchEvent(android.view.MotionEvent event){if(!drawing)return false;int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){int type=event.getToolType(0);if(type==MotionEvent.TOOL_TYPE_STYLUS||type==MotionEvent.TOOL_TYPE_ERASER)lastPen=SystemClock.uptimeMillis();else if(event.getTouchMajor(0)>dp(38)||SystemClock.uptimeMillis()-lastPen<350)return true;if(pointCount()>=150000||marks.size()>=2000){message("Layer full. Save a screenshot and clear annotations to continue.");return true;}strokeBudget=Math.min(20000,150000-pointCount());activePointer=event.getPointerId(0);if(tool.equals("eraser")||type==MotionEvent.TOOL_TYPE_ERASER){erase(event.getX(),event.getY());draft=null;}else {draft=new Mark(tool,color,width);sample(event,0,-1);}wake();return true;}
   if(action==MotionEvent.ACTION_CANCEL){finishStroke();return true;}int index=event.findPointerIndex(activePointer);if(index<0)return true;if(action==MotionEvent.ACTION_MOVE){if(event.getToolType(index)==MotionEvent.TOOL_TYPE_STYLUS)lastPen=SystemClock.uptimeMillis();if(draft!=null){for(int i=0;i<event.getHistorySize();i++)sample(event,index,i);sample(event,index,-1);invalidate();}else if(tool.equals("eraser")||event.getToolType(index)==MotionEvent.TOOL_TYPE_ERASER)erase(event.getX(index),event.getY(index));return true;}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL||(action==MotionEvent.ACTION_POINTER_UP&&event.getPointerId(event.getActionIndex())==activePointer)){finishStroke();return true;}return true;
  }
  private void sample(MotionEvent event,int index,int history){if(draft==null||draft.points.size()>=strokeBudget)return;float px=history<0?event.getX(index):event.getHistoricalX(index,history),py=history<0?event.getY(index):event.getHistoricalY(index,history);float pressure=event.getToolType(index)==MotionEvent.TOOL_TYPE_STYLUS?Math.max(.1f,Math.min(1,history<0?event.getPressure(index):event.getHistoricalPressure(index,history))):1;draft.points.add(new Sample(px/Math.max(1,getWidth()),py/Math.max(1,getHeight()),pressure));}
  private float distance(float px,float py,float ax,float ay,float bx,float by){float dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy==0?1:dx*dx+dy*dy)));return (float)Math.hypot(px-ax-dx*t,py-ay-dy*t);}
  private boolean hit(Mark mark,float px,float py){if(mark.points.isEmpty())return false;float radius=dp(width)+dp(mark.width)/2f;Sample a=mark.points.get(0),b=mark.points.get(mark.points.size()-1);float ax=x(a),ay=y(a),bx=x(b),by=y(b);if(mark.tool.equals("rect"))return Math.min(Math.min(distance(px,py,ax,ay,bx,ay),distance(px,py,bx,ay,bx,by)),Math.min(distance(px,py,bx,by,ax,by),distance(px,py,ax,by,ax,ay)))<radius;if(mark.tool.equals("circle"))return Math.abs(Math.hypot(px-(ax+bx)/2,py-(ay+by)/2)-Math.min(Math.abs(bx-ax),Math.abs(by-ay))/2)<radius;if(mark.tool.equals("line")||mark.points.size()==1)return distance(px,py,ax,ay,bx,by)<radius;for(int i=1;i<mark.points.size();i++)if(distance(px,py,x(mark.points.get(i-1)),y(mark.points.get(i-1)),x(mark.points.get(i)),y(mark.points.get(i)))<radius)return true;return false;}
  private void erase(float px,float py){ArrayList<Mark> remaining=new ArrayList<>();for(Mark mark:marks)if(!hit(mark,px,py))remaining.add(mark);if(remaining.size()!=marks.size()){remember();replace(remaining);save();}}
 }
 private class IconButton extends View {
  final String kind;boolean selected;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);IconButton(String kind){super(DisplayAnnotationService.this);this.kind=kind;setClickable(true);setFocusable(true);}
  @Override protected void onDraw(Canvas c){super.onDraw(c);if(selected){p.setColor(0xff527dff);p.setStyle(Paint.Style.FILL);c.drawRoundRect(4,4,getWidth()-4,getHeight()-4,dp(8),dp(8),p);}c.save();c.translate((getWidth()-dp(24))/2f,(getHeight()-dp(24))/2f);c.scale(dp(24)/24f,dp(24)/24f);p.setColor(Color.WHITE);p.setStrokeWidth(1.8f);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);Path path=new Path();switch(kind){case "grip":for(int y=5;y<=19;y+=7){c.drawCircle(9,y,1,p);c.drawCircle(15,y,1,p);}break;case "mouse":path.moveTo(5,3);path.lineTo(5,20);path.lineTo(10,15);path.lineTo(14,21);path.lineTo(17,19);path.lineTo(13,13);path.lineTo(20,11);path.close();c.drawPath(path,p);break;case "pen":case "marker":path.moveTo(4,16);path.lineTo(16,4);path.lineTo(20,8);path.lineTo(8,20);path.lineTo(3,21);path.close();c.drawPath(path,p);c.drawLine(14,6,18,10,p);if(kind.equals("marker"))c.drawLine(3,23,21,23,p);break;case "eraser":path.moveTo(3,14);path.lineTo(13,3);path.lineTo(21,11);path.lineTo(12,21);path.lineTo(9,21);path.close();c.drawPath(path,p);c.drawLine(7,11,15,19,p);break;case "line":c.drawLine(4,20,20,4,p);break;case "rect":c.drawRect(4,5,20,19,p);break;case "circle":c.drawCircle(12,12,8,p);break;case "laser":c.drawLine(4,20,16,8,p);c.drawCircle(18,5,2,p);c.drawLine(18,0,18,1,p);c.drawLine(23,5,24,5,p);break;case "undo":case "redo":if(kind.equals("redo")){c.translate(24,0);c.scale(-1,1);}path.moveTo(8,4);path.lineTo(3,9);path.lineTo(8,14);path.moveTo(3,9);path.lineTo(13,9);path.cubicTo(23,9,23,20,13,20);c.drawPath(path,p);break;case "capture":c.drawRect(3,6,21,21,p);c.drawCircle(12,13,4,p);c.drawLine(8,6,10,3,p);c.drawLine(10,3,14,3,p);c.drawLine(14,3,16,6,p);break;case "clear":c.drawLine(4,6,20,6,p);c.drawRect(9,3,15,6,p);c.drawRect(6,6,18,21,p);break;case "settings":c.drawCircle(12,12,4,p);for(int i=0;i<8;i++){double a=i*Math.PI/4;c.drawLine(12+(float)Math.cos(a)*8,12+(float)Math.sin(a)*8,12+(float)Math.cos(a)*10,12+(float)Math.sin(a)*10,p);}break;case "return":c.drawRect(5,3,19,21,p);c.drawLine(8,7,16,7,p);c.drawLine(8,11,16,11,p);c.drawLine(8,15,13,15,p);break;}c.restore();}
  @Override public boolean performClick(){super.performClick();return true;}
 }
